        "title": "公司与板块重点",
        "items": [
          "科技仍是最强主线。5月28日创业板指涨1.96%、科创50涨1.59%，盘面上资金继续向AI硬件、半导体、光模块和先进制造集中，说明高景气和高弹性仍压过传统顺周期方向。（来源：中国金融信息网、新华财经）",
          "长鑫科技科创板进程推进，使A股存储链、设备链与国产替代预期再获强化。对中芯国际、兆易创新、半导体ETF的映射更偏正面，但短线也会抬高板块拥挤度。（来源：上交所申报稿静态文件）",
          "券商板块今天的任务不是单独领涨，而是验证市场能否从“科技独强”扩散到“科技+金融”共振。若券商跟不上，盘面很可能演变成高位主线内部轮动。（来源：中国金融信息网、新华社）",
          "地产链仍不具备成为主线的基本面条件。对地产、建材、家居和部分可选消费，更适合把反弹理解为交易性波动，而不是趋势性反转。（来源：国家统计局、Reuters）"
        ]
