          "Reuters称央行近期要求大型银行在5月末加大放贷投放，以避免新增贷款明显失速；这对银行股短期情绪偏中性，但更重要的解读是企业与居民真实融资需求仍然偏弱。（来源：Reuters）",
          "国家统计局发布的1-4月工业利润数据显示，制造业恢复比地产和传统内需更明确，电子、医药和高端装备相关子行业利润改善最突出。（来源：国家统计局）",
          "国家统计局发布的房地产数据继续偏弱，意味着政策若有边际优化，更多是托底而非立刻带来全行业盈利反转。（来源：国家统计局）"
